import java.util.Properties

plugins {
    id("com.android.application")
    id("org.jetbrains.kotlin.android")
    id("org.jetbrains.kotlin.plugin.compose")
}

// Release signing is driven by keystore.properties (generated by scripts/create-keystore.ps1)
// or by ECHOSONAR_* environment variables (useful in CI, where no file should hold a password).
val keystorePropsFile = rootProject.file("keystore.properties")
val keystoreProps = Properties().apply {
    if (keystorePropsFile.exists()) {
        keystorePropsFile.inputStream().use { load(it) }
    }
}
val releaseStoreFile = (System.getenv("ECHOSONAR_STORE_FILE") ?: keystoreProps.getProperty("storeFile"))
    ?.takeIf { it.isNotBlank() }
    ?.let { rootProject.file(it) }
val releaseStorePassword = System.getenv("ECHOSONAR_STORE_PASSWORD") ?: keystoreProps.getProperty("storePassword")
val releaseKeyAlias = System.getenv("ECHOSONAR_KEY_ALIAS") ?: keystoreProps.getProperty("keyAlias")
val releaseKeyPassword = System.getenv("ECHOSONAR_KEY_PASSWORD")
    ?: keystoreProps.getProperty("keyPassword")
    ?: releaseStorePassword
val hasReleaseSigning = releaseStoreFile?.exists() == true &&
    !releaseStorePassword.isNullOrBlank() &&
    !releaseKeyAlias.isNullOrBlank()

android {
    namespace = "com.echosonar"
    compileSdk = 35

    defaultConfig {
        applicationId = "com.echosonar"
        minSdk = 26
        targetSdk = 35
        versionCode = 1
        versionName = "1.0.0"
        resourceConfigurations += listOf("en")
    }

    signingConfigs {
        if (hasReleaseSigning) {
            create("release") {
                storeFile = releaseStoreFile
                storePassword = releaseStorePassword
                keyAlias = releaseKeyAlias
                keyPassword = releaseKeyPassword
            }
        }
    }

    buildTypes {
        debug {
            applicationIdSuffix = ".debug"
            versionNameSuffix = "-debug"
        }
        release {
            isMinifyEnabled = true
            isShrinkResources = true
            proguardFiles(
                getDefaultProguardFile("proguard-android-optimize.txt"),
                "proguard-rules.pro",
            )
            if (hasReleaseSigning) {
                signingConfig = signingConfigs.getByName("release")
            }
        }
    }

    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_17
        targetCompatibility = JavaVersion.VERSION_17
    }

    kotlinOptions {
        jvmTarget = "17"
        freeCompilerArgs += listOf("-Xjvm-default=all")
    }

    buildFeatures {
        compose = true
        buildConfig = true
    }

    packaging {
        resources.excludes += setOf(
            "/META-INF/{AL2.0,LGPL2.1}",
            "/META-INF/DEPENDENCIES",
            "META-INF/*.kotlin_module",
        )
    }

    testOptions {
        unitTests.isReturnDefaultValues = true
    }

    lint {
        warningsAsErrors = false
        abortOnError = false
        checkReleaseBuilds = false
    }
}

